import {DIFFICULTIES,EXITS,NODE,RES,activePlayers,ruleSet,soloEscapeCheck,denounceCheck} from './core.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function difficultyPickerHTML(selected){return `<div class="label-row"><span class="field-label">難易度</span><small>時間・物資・追跡が変わります</small></div><div class="difficulty difficulty-levels">${Object.entries(DIFFICULTIES).map(([id,d])=>`<button data-difficulty="${id}" class="${selected===id?'active':''}" aria-pressed="${selected===id}"><strong>${d.name}</strong><small>${d.rounds}ラウンド</small></button>`).join('')}</div><p class="difficulty-summary">${DIFFICULTIES[selected].description}<br>追跡度${DIFFICULTIES[selected].chaseAt}から追跡 / 拘束${DIFFICULTIES[selected].strikeLimit}回で失敗</p>`}
export function modePickerHTML(count,enabled){if(count<2)return'<p class="solo-mode-note">1人プレイ：自分のペースで帰国作戦</p>';return `<div class="label-row"><span class="field-label">協力ルール</span><small>出発前に選べます</small></div><div class="mode-picker"><button data-betrayal="false" class="${!enabled?'active':''}" aria-pressed="${!enabled}">全員で帰る</button><button data-betrayal="true" class="${enabled?'active danger-mode':''}" aria-pressed="${enabled}">裏切りあり</button></div><p class="mode-summary">${enabled?'密告して通行証を得るか、仲間を待たず単独脱出するか。選択はあなた次第。':'密告・単独脱出なし。3つの任務を分担し、全員の帰国を目指します。'}</p>`}
export function difficultyOptions(selected){return Object.entries(DIFFICULTIES).map(([id,d])=>`<option value="${id}" ${id===selected?'selected':''}>${d.name} / ${d.rounds}ラウンド / 拘束${d.strikeLimit}回で失敗</option>`).join('')}
export function betrayalEntryHTML(g){if(!g.betrayal||g.status!=='playing')return'';const p=g.players[g.turn];return `<button class="betrayal-entry" id="betrayal-btn"><span>♢ 裏切りの選択</span><small>${p.borderPass?'個人通行証を所持':'密告 / 単独脱出'} ↗</small></button>`}
export function betrayalMenuHTML(g,control){
 const p=g.players[g.turn],solo=soloEscapeCheck(g),targets=activePlayers(g).filter(x=>x.id!==p.id);
 return `<span class="eyebrow">TRUST OR BETRAY</span><h2>仲間を信じるか、自分を優先するか。</h2><p>「裏切りあり」の遠征です。密告と単独脱出は任意の選択です。実行すると遠征ログに残り、全員に伝わります。</p><h3>密告して、個人通行証を得る</h3><p>1行動・1人1回。仲間の現在地を追跡隊に知らせ、対象の潜伏を解除し、追跡度を3上げます。見返りの個人通行証は、<strong>自分の単独脱出時だけ追跡度の条件を免除</strong>します。</p>${p.betrayalUsed?'<div class="waiting">密告は使用済みです。</div>':targets.length?`<div class="denounce-targets">${targets.map(t=>{const c=denounceCheck(g,t.id);return `<button class="secondary denounce-target" data-denounce="${t.id}" ${!control||!g.ap||!c.ok?'disabled':''}><span>${esc(t.name)}<small>現在地：${NODE[t.pos].name}</small></span><span>密告 →</span></button>`}).join('')}</div>`:'<p>密告できる未脱出の仲間はいません。</p>'}<h3>仲間を待たず、単独脱出する</h3><p>Aの証明書回収だけを済ませ、脱出地点へ移動すると選べます。B・Cと仲間の集合を待つ必要はありません。<strong>共有物資を消費し、残された人の遠征は続きます。</strong></p>${p.borderPass?'<div class="personal-pass">個人通行証あり：単独脱出時の追跡度条件を免除</div>':''}<div class="solo-exit-requirements">${solo.exit?`<strong>${solo.exit.name} / 自分1人分</strong><p>${Object.entries(solo.need).map(([k,v])=>`${RES[k].label} ${v}`).join('・')}</p>`:'<strong>まずは、5つの脱出地点のどれかへ。</strong><p>単独脱出では各出口の必要物資を半分（端数切り上げ）消費します。</p>'}<small>${solo.ok?'条件を満たしています。自分だけ帰国できます。':esc(solo.reasons.join(' / '))}</small></div><button class="betray-confirm" id="solo-escape-btn" ${!control||!solo.ok?'disabled':''}>自分だけ脱出する →</button><p class="network-tip">密告をしていなくても単独脱出は可能です。その場合は通常の追跡度条件を満たす必要があります。出口に追跡隊がいる場合は、個人通行証があっても陽動が必要です。脱出後は観戦となり、行動順・食料消費・救出人数から外れます。</p>`;
}
export function resultsHTML(g){const legacy=g.version<3,success=p=>p.escaped||legacy&&g.status==='won';return `<div class="individual-results">${g.players.map(p=>`<div class="individual-result ${success(p)?'escaped':'failed'}"><span>${esc(p.name)}<small>${p.betrayalUsed?'密告を選択':p.escapeKind==='solo'?'単独脱出を選択':'仲間と協力'}</small></span><strong>${success(p)?'脱出成功':'未脱出'}<small>${success(p)?esc(EXITS.find(e=>e.id===p.escapeExit)?.name||EXITS.find(e=>e.id===g.ending)?.name||'帰国済み'):'今回の帰国はかなわなかった'}</small></strong></div>`).join('')}</div>`}
export function gameRuleBadgesHTML(g){return `<div class="game-rule-badges"><span>${ruleSet(g).name}</span><span>${g.betrayal?'裏切りあり':g.players.length>1?'全員で帰る':'ソロ'}</span>${g.players.some(p=>p.escaped)?`<span>帰国済み ${g.players.filter(p=>p.escaped).length}/${g.players.length}</span>`:''}</div>`}
